frappe.web_form.after_load = function () {

    // ── Auto-select event from URL hash ──
    const hash = window.location.hash;
    const eventName = hash.startsWith("#event=")
        ? decodeURIComponent(hash.replace("#event=", ""))
        : null;

    console.log("Hash:", hash);
    console.log("Event name to set:", eventName);

    if (eventName) {
        let attempts = 0;
        const iv = setInterval(() => {
            attempts++;
            const fd = frappe.web_form.fields_dict["event"];
            console.log("Attempt", attempts, "field:", fd);
            if (fd && fd.set_value) {
                fd.set_value(eventName);
                fd.df.read_only = 1;
                fd.refresh();
                clearInterval(iv);
            }
            if (attempts >= 30) clearInterval(iv);
        }, 200);
    }

    // ── Meal settings ──
    frappe.call({
        method: "e_desk.e_desk.doctype.participant.participant.get_meal_settings_for_webform",
        callback(r) {
            if (!r.message) return;
            const has_meal = cint(r.message.has_meal);
            const meal_access = r.message.meal_access;

            function set_info_html(html) { $('#info_html').html(html || ''); }

            if (!has_meal) {
                frappe.web_form.set_df_property('meal_included', 'hidden', 1);
                frappe.web_form.set_df_property('meal_preference', 'hidden', 1);
                frappe.web_form.set_value('meal_included', 0);
                set_info_html('');
                return;
            }

            frappe.web_form.set_df_property('meal_included', 'hidden', 1);
            frappe.web_form.set_df_property('meal_preference', 'hidden', 0);
            set_info_html(`
                <div class="alert alert-warning">
                    Meal is a <b>paid add-on</b>. Additional charges apply if you opt for meals.
                </div>
            `);

            if (meal_access === "Free for All Participants") {
                frappe.web_form.set_value('meal_included', 1);
                frappe.web_form.set_df_property('meal_included', 'read_only', 1);
                frappe.web_form.set_df_property('meal_included', 'hidden', 1);
                set_info_html(`
                    <div class="alert alert-success">
                        Meals are <b>free</b>.
                    </div>
                `);
                return;
            }

            frappe.web_form.set_value('meal_included', 0);
            frappe.web_form.set_df_property('meal_included', 'read_only', 0);
        },
        error(err) { console.error("Meal settings error:", err); }
    });

};
